const getDataFiduciaryItems = (
  userRoles: UserRole[],
  userEmail?: string,
): SidebarSection[] => {
  const isRestrictedUser =
    userEmail?.toLowerCase() === "mokshadapagare12@gmail.com";

  const canAccessGrievanceAdmin = hasPermission(
    userRoles,
    Resources.GRIEVANCE_ADMIN,
    Actions.READ,
  );

  const canAccessGrievance = hasPermission(
    userRoles,
    Resources.GRIEVANCE,
    Actions.READ,
  );

  const dpoCenterItems = [
    {
      title: "Dashboard",
      href: "/cms/data-fiduciary/dashboard",
    },
    {
      title: "Consent History",
      href: "/cms/data-fiduciary/consent-history",
    },
  ];

  if (canAccessGrievanceAdmin) {
    dpoCenterItems.push({
      title: "Grievances",
      href: "/cms/data-fiduciary/grievances/admin",
    });
  }

  if (canAccessGrievance) {
    dpoCenterItems.push({
      title: "My Tickets",
      href: "/cms/data-fiduciary/grievances/my-tickets",
    });
  }

  // Policy Center
  const policyCenter: SidebarSection = {
    title: "POLICY CENTER",
    icon: PolicyCenterIcon,
    defaultOpen: false,
    items: [
      {
        title: "Business Unit",
        href: "/cms/data-fiduciary/business-units",
      },
      {
        title: "Business Process",
        href: "/cms/data-fiduciary/business-processes",
      },
      {
        title: "Purpose of Consent",
        href: "/cms/data-fiduciary/consent-purposes",
      },
      {
        title: "Purpose of Processing",
        href: "/cms/data-fiduciary/purposes-of-processing",
      },
      {
        title: "Processors",
        href: "/cms/data-fiduciary/data-processors",
      },
      {
        title: "User Attributes",
        href: "/cms/data-fiduciary/user-attributes",
      },
      {
        title: "Data Retention Policy",
        href: "/cms/data-fiduciary/data-retention",
      },
    ],
  };

  // If this is Moksha's account, show ONLY Policy Center
  if (isRestrictedUser) {
    return [policyCenter];
  }

  // Otherwise show all sections
  return [
    policyCenter,
    {
      title: "DPO CENTER",
      icon: DPOCenterIcon,
      defaultOpen: false,
      items: dpoCenterItems,
    },
    {
      title: "CONSENT CENTER",
      icon: ConsentCenterIcon,
      defaultOpen: false,
      items: [
        {
          title: "Prospective Consent",
          href: "/cms/data-fiduciary/notices",
        },
      ],
    },
    {
      title: "DEVELOPER CENTER",
      icon: Code,
      defaultOpen: false,
      items: [
        {
          title: "API Keys",
          href: "/cms/data-fiduciary/api-keys",
        },
        {
          title: "Webhooks",
          href: "/cms/data-fiduciary/webhooks",
        },
      ],
    },
    {
      title: "ADMIN SETTINGS",
      icon: Settings,
      defaultOpen: false,
      items: [
        {
          title: "User Management",
          href: "/cms/data-fiduciary/users",
        },
        {
          title: "SLA Configuration",
          href: "/cms/data-fiduciary/sla",
        },
      ],
    },
  ];
};